166→// createPipe 在 IPC$ 上打开一个命名管道。
167→func createPipe(ctx *Context, req *wire.CreateRequest) error {
168→	opener := ctx.Conn.Settings.Pipes
169→	if opener == nil {
170→		// 管道后端尚未装配：报「没有这个对象」而不是 NOT_SUPPORTED，
171→		// 客户端会当成共享枚举不可用而优雅退化。
172→		return status.ObjectNameNotFound
173→	}
174→
175→	// 管道名不含路径分隔符，且大小写不敏感。
176→	name := strings.ToLower(strings.Trim(req.Name, `\`))
177→	if name == "" || strings.ContainsAny(name, `\/`) {
178→		return status.ObjectNameInvalid
179→	}
180→
181→	pipe, err := opener.OpenPipe(name, ctx.Session.Identity())
182→	if err != nil {
183→		if errors.Is(err, ErrNoSuchPipe) {
184→			ctx.Log.Debug("请求了未提供的命名管道", "pipe", name)
185→			return status.ObjectNameNotFound
186→		}
187→		ctx.Log.Warn("打开命名管道失败", "pipe", name, "err", err)
188→		return status.FromVFSError(err)
189→	}
190→
191→	open := &Open{
192→		Tree:          ctx.Tree,
193→		Path:          name,
194→		Pipe:          pipe,
195→		GrantedAccess: req.DesiredAccess.Expand(),
196→		ShareAccess:   req.ShareAccess,
197→		CreateAction:  wire.FileOpened,
198→		CreateOptions: req.CreateOptions,
199→		// 管道在 Windows 上报为 NORMAL。
200→		FileAttributes: wire.FileAttributeNormal,
201→	}
202→	if st := ctx.Session.AddOpen(open); st != status.Success {
203→		_ = pipe.Close()
204→		return st
205→	}
206→	ctx.Chain.LastOpen = open
207→
208→	// 管道没有真正的时间戳与长度，全部回 0 —— 客户端不看这些字段。
209→	resp := &wire.CreateResponse{
210→		OplockLevel:    wire.OplockLevelNone,
211→		CreateAction:   wire.FileOpened,
212→		FileAttributes: wire.FileAttributeNormal,
213→		FileID:         wire.FileID{Persistent: open.Persistent, Volatile: open.Volatile},
214→	}
215→	out, err := resp.Append(ctx.Out)
216→	if err != nil {
217→		return status.InsuffServerResources
218→	}
219→	ctx.Out = out
220→
221→	ctx.Log.Debug("打开命名管道", "pipe", name, "fid", open.Volatile)
222→	return nil
223→}
224→
225→// splitCreateName 把 CREATE 的 Name 拆成「共享内相对路径」与「流名」。
226→//
227→// 线格式用反斜杠分隔且无前导反斜杠（protocol-notes §8），VFS 用正斜杠。
228→// 流名语法是 `path:stream:$DATA`（MS-FSCC §2.1.5.4）。
229→//
230→// 真正的路径穿越防御在 VFS 层（AGENTS.md §8），这里只做**语法**校验：
231→// 拒绝绝对路径与显然畸形的输入，避免把垃圾喂给下层。
232→func splitCreateName(name string) (path, stream string, err error) {
233→	if strings.ContainsRune(name, 0) {
234→		return "", "", status.ObjectNameInvalid
235→	}
236→	// 客户端偶尔会带前导反斜杠，容忍之。
237→	name = strings.TrimPrefix(name, `\`)
238→	name = strings.ReplaceAll(name, `\`, "/")
239→
240→	if i := strings.IndexByte(name, ':'); i >= 0 {
241→		path, stream = name[:i], name[i+1:]
242→		// 去掉 `:$DATA` 后缀；类型不是 $DATA 的流我们不支持。
243→		if j := strings.IndexByte(stream, ':'); j >= 0 {
244→			if !strings.EqualFold(stream[j:], ":$DATA") {
245→				return "", "", status.NotSupported
246→			}
247→			stream = stream[:j]
248→		}
249→		if stream == "" {
250→			// `file::$DATA` 就是主数据流。
251→			stream = ""
252→		}
253→	} else {
254→		path = name
255→	}
256→
257→	// vfs.CleanPath 负责规范化并拒绝 ".."、绝对路径等越界写法。
258→	clean, cerr := vfs.CleanPath(path)
259→	if cerr != nil {
260→		return "", "", status.ObjectPathInvalid
261→	}
262→	return clean, stream, nil
263→}
264→
265→// openFlags 把 SMB 的 DesiredAccess/CreateOptions 翻译成 vfs.OpenFlags。
266→func openFlags(access wire.Access, opts wire.CreateOptions) vfs.OpenFlags {
267→	var f vfs.OpenFlags
268→
269→	if access&(wire.FileReadData|wire.FileExecute) != 0 {
270→		f |= vfs.OpenRead
271→	}
272→	if access&(wire.FileWriteData) != 0 {
273→		f |= vfs.OpenWrite
274→	}
275→	if access&wire.FileAppendData != 0 {
276→		f |= vfs.OpenAppend
277→	}
278→	// 只要了属性/EA/ACL 而没要数据流：告诉后端可以走轻量路径。
279→	// Explorer 与 Finder 会为列表里的每个文件做这种探测，量很大。
280→	if f == 0 {
281→		f |= vfs.OpenAttrOnly
282→	}
283→
284→	if opts&wire.FileDirectoryFile != 0 {
285→		f |= vfs.OpenDirectory
286→	}
287→	if opts&wire.FileNonDirectoryFile != 0 {
288→		f |= vfs.OpenNonDirectory
289→	}
290→	if opts&wire.FileOpenReparsePoint != 0 {
291→		f |= vfs.OpenNoFollow
292→	}
293→	if opts&wire.FileWriteThrough != 0 {
294→		f |= vfs.OpenWriteThrough
295→	}
296→	if opts&wire.FileDeleteOnClose != 0 {
297→		f |= vfs.OpenDeleteOnClose
298→	}
299→	return f
300→}
301→
302→// maximalAccessFor 返回 MAXIMUM_ALLOWED 在本树上应当授予的访问掩码。
303→func maximalAccessFor(t *Tree) wire.Access {
304→	if t.Writable() {
305→		return wire.Access(wire.MaximalAccessReadWrite)
306→	}
307→	return wire.Access(wire.MaximalAccessReadOnly)
308→}
309→
310→// createStatus 把 VFS 错误映射为 CREATE 语境下的 NTSTATUS。
311→//
312→// 与通用映射的差别只有一处：CREATE 语境里 ErrExist 的含义取决于
313→// disposition —— FILE_CREATE 下是「已存在」，其它情况下是「名字冲突」。
314→func createStatus(err error, disp wire.CreateDisposition) status.Status {
315→	if errors.Is(err, vfs.ErrExist) && disp == wire.FileCreate {
316→		return status.ObjectNameCollision
317→	}
318→	return status.FromVFSError(err)
319→}
320→
321→// createResponseContexts 生成要回给客户端的 create context 链。
322→//
323→// 目前支持两个：
324→//   - "QFid"（请求稳定 FileId）—— macOS 与 Windows 都会带，
325→//     回它可以让客户端少发一轮 QUERY_INFO；
326→//   - "AAPL"（Apple 扩展）—— 由 negotiateAAPL 预先算好，见 aapl.go。
327→//
328→// 其余 context（DHnQ/RqLs 等）属于后续阶段，**不认识的 context 必须静默忽略**
329→// 而不是报错（MS-SMB2 §3.3.5.9：服务端忽略不支持的 create context）。
330→func createResponseContexts(req *wire.CreateRequest, attr *vfs.Attr, aapl []byte) []wire.CreateContext {
331→	var out []wire.CreateContext
332→	if _, ok := wire.FindCreateContext(req.Contexts, wire.CreateContextQFid); ok {
333→		out = append(out, wire.CreateContext{
334→			Name: wire.CreateContextQFid,
335→			Data: wire.DiskIDContext{DiskFileID: attr.FileID}.Encode(),
336→		})
337→	}
338→	if len(aapl) > 0 {
339→		out = append(out, wire.CreateContext{
340→			Name: wire.CreateContextAAPL,
341→			Data: aapl,
342→		})
343→	}
344→	return out
345→}
