143→// TestBuildAAPLResponseBitmapSegments 验证「只返回被请求的段」。
144→func TestBuildAAPLResponseBitmapSegments(t *testing.T) {
145→	tests := []struct {
146→		name    string
147→		bitmap  uint64
148→		wantLen int
149→	}{
150→		{"什么都不要", 0, 16},
151→		{"只要 ServerCaps", aaplServerCaps, 24},
152→		{"只要 VolumeCaps", aaplVolumeCaps, 24},
153→		{"只要 ModelInfo", aaplModelInfo, 16 + 8 + 2*len("MacSamba")},
154→		{"全都要", aaplServerCaps | aaplVolumeCaps | aaplModelInfo, 40 + 2*len("MacSamba")},
155→	}
156→	for _, tc := range tests {
157→		t.Run(tc.name, func(t *testing.T) {
158→			got := buildAAPLResponse(tc.bitmap, aaplUnixBased, aaplSupportsFullSync, "MacSamba")
159→			if len(got) != tc.wantLen {
160→				t.Errorf("长度 = %d, 期望 %d", len(got), tc.wantLen)
161→			}
162→			if v := aaplLE.Uint64(got[8:16]); v != tc.bitmap {
163→				t.Errorf("ReplyBitmap = %#x, 期望 %#x", v, tc.bitmap)
164→			}
165→			// VolumeCaps 单独被请求时必须紧跟在头后面，不能留 ServerCaps 的空洞。
166→			if tc.bitmap == aaplVolumeCaps {
167→				if v := aaplLE.Uint64(got[16:24]); v != aaplSupportsFullSync {
168→					t.Errorf("VolumeCapabilities = %#x, 期望 %#x", v, aaplSupportsFullSync)
169→				}
170→			}
171→		})
172→	}
173→}
