func (s *aaplDirAttrSource) childPath(name string) (string, bool) {
	switch name {
	case ".":
		return s.dir, true
	case "..":
		return "", false
	}
	if s.dir == "" {
		return name, true
	}
	return s.dir + "/" + name, true
