 14→}
 15→
 16→// handleQueryDirectory 处理 SMB2 QUERY_DIRECTORY（MS-SMB2 §3.3.5.18）。
 17→//
 18→// 语义要点（protocol-notes §9，非常容易踩错）：
 19→//   - 搜索模式只在**首次**（或带 SMB2_RESTART_SCANS 时）携带，
 20→//     后续调用沿用同一句柄上的模式，枚举位置也保存在句柄里；
 21→//   - 首次调用就没有任何匹配 → STATUS_NO_SUCH_FILE；
 22→//   - 之前吐过条目、这次没有了 → STATUS_NO_MORE_FILES；
 23→//     两者搞混会让客户端要么少显示文件、要么无限循环。
 24→//   - 输出必须 8 字节对齐并回填 NextEntryOffset，由 wire.DirEntryWriter 负责。
 25→func handleQueryDirectory(ctx *Context) error {
 26→	req, err := wire.ParseQueryDirectoryRequest(ctx.Msg)
 27→	if err != nil {
 28→		return status.InvalidParameter
 29→	}
 30→
 31→	open, err := ctx.resolveOpen(req.FileID)
 32→	if err != nil {
 33→		return err
 34→	}
 35→	if !open.IsDir {
 36→		return status.InvalidParameter
 37→	}
 38→	if open.GrantedAccess&wire.FileReadData == 0 {
 39→		// FILE_LIST_DIRECTORY 与 FILE_READ_DATA 是同一个位。
 40→		return status.AccessDenied
 41→	}
 42→	if open.Handle == nil {
 43→		return status.FileClosed
 44→	}
 45→
 46→	// 输出上限同时受客户端请求与协商出的 MaxTransactSize 约束
 47→	// （AGENTS.md §8：目录枚举缓冲必须有上限）。
 48→	maxOut := int(req.OutputBufferLength)
 49→	if maxOut <= 0 {
 50→		return status.InvalidParameter
 51→	}
 52→	if maxOut > int(ctx.Conn.MaxTransactSize) {
 53→		maxOut = int(ctx.Conn.MaxTransactSize)
 54→	}
 55→
 56→	pattern, first := open.DirScan(req.FileName, req.Restart())
 57→
 58→	// SMB2_RETURN_SINGLE_ENTRY：一次只要一条。
 59→	batch := 0
 60→	if req.SingleEntry() {
 61→		batch = 1
 62→	}
 63→
 64→	entries, rerr := open.ReadDir(pattern, req.Restart(), batch)
 65→	if rerr != nil && !errors.Is(rerr, io.EOF) {
 66→		return status.FromVFSError(rerr)
 67→	}
 68→	if len(entries) == 0 {
 69→		return noMoreFiles(first)
 70→	}
 71→
 72→	// Apple 扩展：协商过 kAAPL_SUPPORTS_READ_DIR_ATTR 后，
 73→	// FileIdBothDirectoryInformation 的 EaSize/ShortName 区改放 Apple 元数据
 74→	// （见 aapl.go）。未协商时 src 为 nil，走标准布局。
 75→	src := newAAPLDirAttrSource(ctx, open, req.FileInformationClass)
 76→
 77→	w := wire.NewDirEntryWriter(req.FileInformationClass, maxOut)
 78→	written := 0
 79→	for i := range entries {
 80→		// 记录本条目录项在缓冲里的起点，供随后的 Apple 字段就地改写。
 81→		// 规则与 wire.DirEntryWriter.Add 一致：第一条紧贴缓冲起点，
 82→		// 后续条目落在 8 字节对齐处。
 83→		start := w.Len()
 84→		if w.Count() > 0 {
 85→			start = (start + 7) &^ 7
 86→		}
 87→
 88→		ok, werr := w.Add(dirEntry(&entries[i]))
 89→		if werr != nil {
 90→			// 不认识的 information class。
 91→			return status.InvalidInfoClass
 92→		}
 93→		if !ok {
 94→			// 缓冲放不下了：把没写进去的条目退回句柄，下一轮再来。
 95→			open.UnreadDir(entries[i:])
 96→			break
 97→		}
 98→		if src != nil {
 99→			attr := src.entry(&entries[i])
100→			attr.patchIDBothDirEntry(w.Bytes(), start)
101→		}
102→		written++
103→	}
104→
105→	if written == 0 {
106→		// 一条都放不下：客户端给的缓冲太小，连一个条目都装不了。
107→		return status.InfoLengthMismatch
108→	}
109→
110→	resp := &wire.QueryDirectoryResponse{Buffer: w.Bytes()}
111→	out, aerr := resp.Append(ctx.Out)
112→	if aerr != nil {
113→		return status.InsuffServerResources
114→	}
115→	ctx.Out = out
116→	return nil
117→}
118→
119→// noMoreFiles 区分「首次枚举就无匹配」与「枚举已结束」。
120→func noMoreFiles(first bool) error {
121→	if first {
122→		// 模式没匹配到任何东西。
123→		return status.NoSuchFile
124→	}
125→	return status.NoMoreFiles
126→}
127→
128→// dirEntry 把 VFS 目录项翻译成线格式目录项。
129→func dirEntry(e *vfs.DirEntry) wire.DirEntry {
130→	return wire.DirEntry{
131→		CreationTime:   vfs.TimeToFiletime(e.Attr.CreateTime),
132→		LastAccessTime: vfs.TimeToFiletime(e.Attr.AccessTime),
133→		LastWriteTime:  vfs.TimeToFiletime(e.Attr.WriteTime),
134→		ChangeTime:     vfs.TimeToFiletime(e.Attr.ChangeTime),
135→		EndOfFile:      uint64(e.Attr.Size),
136→		AllocationSize: uint64(e.Attr.Alloc),
137→		FileAttributes: wire.FileAttributes(e.Attr.FileAttributes),
138→		FileID:         e.Attr.FileID,
139→		Name:           e.Name,
140→	}
141→}
