170→// createPipe 在 IPC$ 上打开一个命名管道。
171→func createPipe(ctx *Context, req *wire.CreateRequest) error {
172→	opener := ctx.Conn.Settings.Pipes
173→	if opener == nil {
174→		// 管道后端尚未装配：报「没有这个对象」而不是 NOT_SUPPORTED，
175→		// 客户端会当成共享枚举不可用而优雅退化。
176→		return status.ObjectNameNotFound
177→	}
178→
179→	// 管道名不含路径分隔符，且大小写不敏感。
180→	name := strings.ToLower(strings.Trim(req.Name, `\`))
181→	if name == "" || strings.ContainsAny(name, `\/`) {
182→		return status.ObjectNameInvalid
183→	}
184→
185→	pipe, err := opener.OpenPipe(name, ctx.Session.Identity())
186→	if err != nil {
187→		if errors.Is(err, ErrNoSuchPipe) {
188→			ctx.Log.Debug("请求了未提供的命名管道", "pipe", name)
189→			return status.ObjectNameNotFound
190→		}
191→		ctx.Log.Warn("打开命名管道失败", "pipe", name, "err", err)
192→		return status.FromVFSError(err)
193→	}
194→
195→	open := &Open{
196→		Tree:          ctx.Tree,
197→		Path:          name,
198→		Pipe:          pipe,
199→		GrantedAccess: req.DesiredAccess.Expand(),
200→		ShareAccess:   req.ShareAccess,
201→		CreateAction:  wire.FileOpened,
202→		CreateOptions: req.CreateOptions,
203→		// 管道在 Windows 上报为 NORMAL。
204→		FileAttributes: wire.FileAttributeNormal,
205→	}
206→	if st := ctx.Session.AddOpen(open); st != status.Success {
207→		_ = pipe.Close()
208→		return st
209→	}
210→	ctx.Chain.LastOpen = open
211→
212→	// 管道没有真正的时间戳与长度，全部回 0 —— 客户端不看这些字段。
213→	resp := &wire.CreateResponse{
214→		OplockLevel:    wire.OplockLevelNone,
215→		CreateAction:   wire.FileOpened,
216→		FileAttributes: wire.FileAttributeNormal,
217→		FileID:         wire.FileID{Persistent: open.Persistent, Volatile: open.Volatile},
218→	}
219→	out, err := resp.Append(ctx.Out)
220→	if err != nil {
221→		return status.InsuffServerResources
222→	}
223→	ctx.Out = out
224→
225→	ctx.Log.Debug("打开命名管道", "pipe", name, "fid", open.Volatile)
226→	return nil
227→}
228→
229→// splitCreateName 把 CREATE 的 Name 拆成「共享内相对路径」与「流名」。
230→//
231→// 线格式用反斜杠分隔且无前导反斜杠（protocol-notes §8），VFS 用正斜杠。
232→// 流名语法是 `path:stream:$DATA`（MS-FSCC §2.1.5.4）。
233→//
234→// 真正的路径穿越防御在 VFS 层（AGENTS.md §8），这里只做**语法**校验：
235→// 拒绝绝对路径与显然畸形的输入，避免把垃圾喂给下层。
236→func splitCreateName(name string) (path, stream string, err error) {
237→	if strings.ContainsRune(name, 0) {
238→		return "", "", status.ObjectNameInvalid
239→	}
240→	// 客户端偶尔会带前导反斜杠，容忍之。
241→	name = strings.TrimPrefix(name, `\`)
242→	name = strings.ReplaceAll(name, `\`, "/")
243→
244→	if i := strings.IndexByte(name, ':'); i >= 0 {
245→		path, stream = name[:i], name[i+1:]
246→		// 去掉 `:$DATA` 后缀；类型不是 $DATA 的流我们不支持。
247→		if j := strings.IndexByte(stream, ':'); j >= 0 {
248→			if !strings.EqualFold(stream[j:], ":$DATA") {
249→				return "", "", status.NotSupported
250→			}
251→			stream = stream[:j]
252→		}
253→		if stream == "" {
254→			// `file::$DATA` 就是主数据流。
255→			stream = ""
256→		}
257→	} else {
258→		path = name
259→	}
260→
261→	// vfs.CleanPath 负责规范化并拒绝 ".."、绝对路径等越界写法。
262→	clean, cerr := vfs.CleanPath(path)
263→	if cerr != nil {
264→		return "", "", status.ObjectPathInvalid
265→	}
266→	return clean, stream, nil
267→}
268→
269→// openFlags 把 SMB 的 DesiredAccess/CreateOptions 翻译成 vfs.OpenFlags。
270→func openFlags(access wire.Access, opts wire.CreateOptions) vfs.OpenFlags {
271→	var f vfs.OpenFlags
272→
273→	if access&(wire.FileReadData|wire.FileExecute) != 0 {
274→		f |= vfs.OpenRead
275→	}
276→	if access&(wire.FileWriteData) != 0 {
277→		f |= vfs.OpenWrite
278→	}
279→	if access&wire.FileAppendData != 0 {
280→		f |= vfs.OpenAppend
281→	}
282→	// 只要了属性/EA/ACL 而没要数据流：告诉后端可以走轻量路径。
283→	// Explorer 与 Finder 会为列表里的每个文件做这种探测，量很大。
284→	if f == 0 {
285→		f |= vfs.OpenAttrOnly
286→	}
287→
288→	if opts&wire.FileDirectoryFile != 0 {
289→		f |= vfs.OpenDirectory
290→	}
291→	if opts&wire.FileNonDirectoryFile != 0 {
292→		f |= vfs.OpenNonDirectory
293→	}
294→	if opts&wire.FileOpenReparsePoint != 0 {
295→		f |= vfs.OpenNoFollow
296→	}
297→	if opts&wire.FileWriteThrough != 0 {
298→		f |= vfs.OpenWriteThrough
299→	}
300→	if opts&wire.FileDeleteOnClose != 0 {
301→		f |= vfs.OpenDeleteOnClose
302→	}
303→	return f
304→}
305→
306→// applyAllocationSize 处理 "AlSi" create context（MS-SMB2 §2.2.13.2.2）：
307→// 客户端要求为新建的文件**预留**这么多磁盘空间。
308→//
309→// 为什么要实现：Time Machine 的 .sparsebundle 由成千上万个固定大小
310→// （通常 8 MiB）的 band 文件组成，macOS 建每个 band 时都会带 AlSi。
311→// 不预留的话这些文件在 ext4 上会被写得很碎，后续顺序读整个备份会明显变慢。
312→//
313→// 语义与 Windows 的 AllocationSize 一致：**只占块、不改 EOF**
314→// （vfs 的 Preallocate 用 FALLOC_FL_KEEP_SIZE 实现）。
315→//
316→// 失败一律只记日志不报错：预留不成功文件照样能用，只是可能更碎片化；
317→// 为此让整个 CREATE 失败得不偿失。后端不支持（如 Windows/其它平台）同理。
318→func applyAllocationSize(ctx *Context, req *wire.CreateRequest, h vfs.Handle, action vfs.Action) {
319→	data, ok := wire.FindCreateContext(req.Contexts, wire.CreateContextAlSi)
320→	if !ok {
321→		return
322→	}
323→	size, err := wire.AllocationSizeContext(data)
324→	if err != nil {
325→		ctx.Log.Debug("AlSi create context 长度非法", "len", len(data))
326→		return
327→	}
328→	// 超出 int64 的值只可能是畸形输入（AGENTS.md §8：用之前先校验边界）。
329→	if size == 0 || size > math.MaxInt64 {
330→		return
331→	}
332→	// 只在文件被新建/覆盖时预留。对一个**已存在**的文件做预留会悄悄改变
333→	// 它的磁盘占用，而客户端此时只是想打开它。
334→	switch action {
335→	case vfs.ActionCreated, vfs.ActionOverwritten, vfs.ActionSuperseded:
336→	default:
337→		return
338→	}
339→
340→	sp, ok := h.(vfs.SparseFile)
341→	if !ok {
342→		return
343→	}
344→	if err := sp.Preallocate(0, int64(size)); err != nil {
345→		ctx.Log.Debug("AlSi 预留空间失败", "size", size, "err", err)
346→	}
347→}
348→
349→// maximalAccessFor 返回 MAXIMUM_ALLOWED 在本树上应当授予的访问掩码。
350→func maximalAccessFor(t *Tree) wire.Access {
351→	if t.Writable() {
352→		return wire.Access(wire.MaximalAccessReadWrite)
353→	}
354→	return wire.Access(wire.MaximalAccessReadOnly)
355→}
356→
357→// createStatus 把 VFS 错误映射为 CREATE 语境下的 NTSTATUS。
358→//
359→// 与通用映射的差别只有一处：CREATE 语境里 ErrExist 的含义取决于
360→// disposition —— FILE_CREATE 下是「已存在」，其它情况下是「名字冲突」。
361→func createStatus(err error, disp wire.CreateDisposition) status.Status {
362→	if errors.Is(err, vfs.ErrExist) && disp == wire.FileCreate {
363→		return status.ObjectNameCollision
364→	}
365→	return status.FromVFSError(err)
366→}
367→
368→// createResponseContexts 生成要回给客户端的 create context 链。
369→//
370→// 目前支持两个：
371→//   - "QFid"（请求稳定 FileId）—— macOS 与 Windows 都会带，
372→//     回它可以让客户端少发一轮 QUERY_INFO；
373→//   - "AAPL"（Apple 扩展）—— 由 negotiateAAPL 预先算好，见 aapl.go。
374→//
375→// 其余 context（DHnQ/RqLs 等）属于后续阶段，**不认识的 context 必须静默忽略**
376→// 而不是报错（MS-SMB2 §3.3.5.9：服务端忽略不支持的 create context）。
377→func createResponseContexts(req *wire.CreateRequest, attr *vfs.Attr, aapl []byte) []wire.CreateContext {
378→	var out []wire.CreateContext
379→	if _, ok := wire.FindCreateContext(req.Contexts, wire.CreateContextQFid); ok {
380→		out = append(out, wire.CreateContext{
381→			Name: wire.CreateContextQFid,
382→			Data: wire.DiskIDContext{DiskFileID: attr.FileID}.Encode(),
383→		})
384→	}
385→	if len(aapl) > 0 {
386→		out = append(out, wire.CreateContext{
387→			Name: wire.CreateContextAAPL,
388→			Data: aapl,
389→		})
390→	}
391→	return out
392→}
