 17→// handleCreate 处理 SMB2 CREATE（MS-SMB2 §3.3.5.9）。
 18→//
 19→// CREATE 是整个协议里语义最重的命令：它同时承担 open / create / truncate /
 20→// mkdir / delete-on-close 五件事，具体做哪件由 CreateDisposition 与
 21→// CreateOptions 的组合决定。这里把这些组合翻译成 vfs.OpenRequest，
 22→// 真正的路径校验与 IO 由 VFS 层负责（AGENTS.md §8：路径穿越防御统一在 VFS）。
 23→func handleCreate(ctx *Context) error {
 24→	req, err := wire.ParseCreateRequest(ctx.Msg)
 25→	if err != nil {
 26→		ctx.Log.Debug("CREATE 请求解析失败", "err", err)
 27→		return status.InvalidParameter
 28→	}
 29→
 30→	if ctx.Tree.IsIPC() {
 31→		return createPipe(ctx, req)
 32→	}
 33→	return createFile(ctx, req)
 34→}
