 36→// createFile 在磁盘共享上打开/创建对象。
 37→func createFile(ctx *Context, req *wire.CreateRequest) error {
 38→	fs := ctx.Tree.FS()
 39→	if fs == nil {
 40→		return status.NetworkNameDeleted
 41→	}
 42→
 43→	// 不支持按 FileId 打开（需要一张全卷 FileId→路径表，且客户端有回退路径）。
 44→	if req.CreateOptions&wire.FileOpenByFileID != 0 {
 45→		return status.NotSupported
 46→	}
 47→
 48→	path, stream, err := splitCreateName(req.Name)
 49→	if err != nil {
 50→		return err
 51→	}
 52→
 53→	// Apple 扩展协商放在真正打开文件**之前**：与 Samba vfs_fruit 的
 54→	// check_aapl() 位置一致，且失败时没有句柄要回收。
 55→	aapl, err := negotiateAAPL(ctx, req)
 56→	if err != nil {
 57→		return err
 58→	}
 59→
 60→	// GENERIC_* 要先展开成具体位，后续判定才有意义（MS-DTYP §2.4.3）。
 61→	access := req.DesiredAccess.Expand()
 62→	// MAXIMUM_ALLOWED：按本树允许的上限授予。授权依据是配置，不是宿主 ACL。
 63→	if access&wire.MaximumAllowed != 0 {
 64→		access = maximalAccessFor(ctx.Tree)
 65→	}
 66→
 67→	writing := access&(wire.FileWriteData|wire.FileAppendData|wire.FileWriteEA|
 68→		wire.FileWriteAttributes|wire.Delete|wire.WriteDAC|wire.WriteOwner) != 0
 69→	// 除 FILE_OPEN 外的所有 disposition 都会改动文件系统。
 70→	mutating := req.CreateDisposition != wire.FileOpen
 71→	if writing || mutating {
 72→		if err := ctx.RequireWritable(); err != nil {
 73→			return err
 74→		}
 75→	}
 76→
 77→	openReq := &vfs.OpenRequest{
 78→		Path:           path,
 79→		Stream:         stream,
 80→		Flags:          openFlags(access, req.CreateOptions),
 81→		Disposition:    vfs.Disposition(req.CreateDisposition),
 82→		FileAttributes: uint32(req.FileAttributes),
 83→	}
 84→
 85→	h, action, err := fs.Open(openReq)
 86→	if err != nil {
 87→		ctx.Log.Debug("CREATE 打开失败", "path", path, "stream", stream, "err", err)
 88→		return createStatus(err, req.CreateDisposition)
 89→	}
 90→
 91→	// AlSi 要在 Stat 之前做，响应里的 AllocationSize 才是预留之后的值。
 92→	applyAllocationSize(ctx, req, h, action)
 93→
 94→	attr, err := h.Stat()
 95→	if err != nil {
 96→		_ = h.Close()
 97→		return status.FromVFSError(err)
 98→	}
 99→
100→	isDir := attr.FileAttributes&vfs.FileAttributeDirectory != 0
101→	// FILE_DIRECTORY_FILE / FILE_NON_DIRECTORY_FILE 是硬性断言，
102→	// VFS 后端可能没能力提前判断，这里兜底（MS-SMB2 §3.3.5.9）。
103→	if req.CreateOptions&wire.FileDirectoryFile != 0 && !isDir {
104→		_ = h.Close()
105→		return status.NotADirectory
106→	}
107→	if req.CreateOptions&wire.FileNonDirectoryFile != 0 && isDir {
108→		_ = h.Close()
109→		return status.FileIsADirectory
110→	}
111→
112→	open := &Open{
113→		Tree:           ctx.Tree,
114→		Path:           path,
115→		Stream:         stream,
116→		Handle:         h,
117→		IsDir:          isDir,
118→		GrantedAccess:  access,
119→		ShareAccess:    req.ShareAccess,
120→		CreateAction:   wire.CreateAction(action),
121→		CreateOptions:  req.CreateOptions,
122→		FileAttributes: wire.FileAttributes(attr.FileAttributes),
123→	}
124→	if req.CreateOptions&wire.FileDeleteOnClose != 0 {
125→		if err := ctx.RequireWritable(); err != nil {
126→			_ = h.Close()
127→			return err
128→		}
129→		open.SetDeleteOnClose(true)
130→		// vfs 层在 OpenDeleteOnClose 下会在 Close 时自行删除文件，
131→		// 命令层 CLOSE handler 必须让出，避免重复删除（见 close.go）。
132→		open.vfsOwnsDelete = true
133→	}
134→
135→	if st := ctx.Session.AddOpen(open); st != status.Success {
136→		_ = h.Close()
137→		return st
138→	}
139→	ctx.Chain.LastOpen = open
140→
141→	resp := &wire.CreateResponse{
142→		// 不实现 oplock/lease：一律回 NONE。客户端会退化成不缓存，
143→		// 正确性不受影响（protocol-notes §9）。
144→		OplockLevel:    wire.OplockLevelNone,
145→		CreateAction:   open.CreateAction,
146→		CreationTime:   vfs.TimeToFiletime(attr.CreateTime),
147→		LastAccessTime: vfs.TimeToFiletime(attr.AccessTime),
148→		LastWriteTime:  vfs.TimeToFiletime(attr.WriteTime),
149→		ChangeTime:     vfs.TimeToFiletime(attr.ChangeTime),
150→		AllocationSize: uint64(attr.Alloc),
151→		EndOfFile:      uint64(attr.Size),
152→		FileAttributes: wire.FileAttributes(attr.FileAttributes),
153→		FileID:         wire.FileID{Persistent: open.Persistent, Volatile: open.Volatile},
154→		Contexts:       createResponseContexts(req, attr, aapl),
155→	}
156→
157→	out, err := resp.Append(ctx.Out)
158→	if err != nil {
159→		ctx.Log.Error("编码 CREATE Response 失败", "err", err)
160→		return status.InsuffServerResources
161→	}
162→	ctx.Out = out
163→
164→	ctx.Log.Debug("CREATE",
165→		"share", ctx.Tree.Share.Name, "path", path, "dir", isDir,
166→		"action", action, "fid", open.Volatile)
167→	return nil
168→}
