229→// splitCreateName 把 CREATE 的 Name 拆成「共享内相对路径」与「流名」。
230→//
231→// 线格式用反斜杠分隔且无前导反斜杠（protocol-notes §8），VFS 用正斜杠。
232→// 流名语法是 `path:stream:$DATA`（MS-FSCC §2.1.5.4）。
233→//
234→// 真正的路径穿越防御在 VFS 层（AGENTS.md §8），这里只做**语法**校验：
235→// 拒绝绝对路径与显然畸形的输入，避免把垃圾喂给下层。
236→func splitCreateName(name string) (path, stream string, err error) {
237→	if strings.ContainsRune(name, 0) {
238→		return "", "", status.ObjectNameInvalid
239→	}
240→	// 客户端偶尔会带前导反斜杠，容忍之。
241→	name = strings.TrimPrefix(name, `\`)
242→	name = strings.ReplaceAll(name, `\`, "/")
243→
244→	if i := strings.IndexByte(name, ':'); i >= 0 {
245→		path, stream = name[:i], name[i+1:]
246→		// 去掉 `:$DATA` 后缀；类型不是 $DATA 的流我们不支持。
247→		if j := strings.IndexByte(stream, ':'); j >= 0 {
248→			if !strings.EqualFold(stream[j:], ":$DATA") {
249→				return "", "", status.NotSupported
250→			}
251→			stream = stream[:j]
252→		}
253→		if stream == "" {
254→			// `file::$DATA` 就是主数据流。
255→			stream = ""
256→		}
257→	} else {
258→		path = name
259→	}
260→
261→	// vfs.CleanPath 负责规范化并拒绝 ".."、绝对路径等越界写法。
262→	clean, cerr := vfs.CleanPath(path)
263→	if cerr != nil {
264→		return "", "", status.ObjectPathInvalid
265→	}
266→	return clean, stream, nil
267→}
