269→// openFlags 把 SMB 的 DesiredAccess/CreateOptions 翻译成 vfs.OpenFlags。
270→func openFlags(access wire.Access, opts wire.CreateOptions) vfs.OpenFlags {
271→	var f vfs.OpenFlags
272→
273→	if access&(wire.FileReadData|wire.FileExecute) != 0 {
274→		f |= vfs.OpenRead
275→	}
276→	if access&(wire.FileWriteData) != 0 {
277→		f |= vfs.OpenWrite
278→	}
279→	if access&wire.FileAppendData != 0 {
280→		f |= vfs.OpenAppend
281→	}
282→	// 只要了属性/EA/ACL 而没要数据流：告诉后端可以走轻量路径。
283→	// Explorer 与 Finder 会为列表里的每个文件做这种探测，量很大。
284→	if f == 0 {
285→		f |= vfs.OpenAttrOnly
286→	}
287→
288→	if opts&wire.FileDirectoryFile != 0 {
289→		f |= vfs.OpenDirectory
290→	}
291→	if opts&wire.FileNonDirectoryFile != 0 {
292→		f |= vfs.OpenNonDirectory
293→	}
294→	if opts&wire.FileOpenReparsePoint != 0 {
295→		f |= vfs.OpenNoFollow
296→	}
297→	if opts&wire.FileWriteThrough != 0 {
298→		f |= vfs.OpenWriteThrough
299→	}
300→	if opts&wire.FileDeleteOnClose != 0 {
301→		f |= vfs.OpenDeleteOnClose
302→	}
303→	return f
304→}
