306→// applyAllocationSize 处理 "AlSi" create context（MS-SMB2 §2.2.13.2.2）：
307→// 客户端要求为新建的文件**预留**这么多磁盘空间。
308→//
309→// 为什么要实现：Time Machine 的 .sparsebundle 由成千上万个固定大小
310→// （通常 8 MiB）的 band 文件组成，macOS 建每个 band 时都会带 AlSi。
311→// 不预留的话这些文件在 ext4 上会被写得很碎，后续顺序读整个备份会明显变慢。
312→//
313→// 语义与 Windows 的 AllocationSize 一致：**只占块、不改 EOF**
314→// （vfs 的 Preallocate 用 FALLOC_FL_KEEP_SIZE 实现）。
315→//
316→// 失败一律只记日志不报错：预留不成功文件照样能用，只是可能更碎片化；
317→// 为此让整个 CREATE 失败得不偿失。后端不支持（如 Windows/其它平台）同理。
318→func applyAllocationSize(ctx *Context, req *wire.CreateRequest, h vfs.Handle, action vfs.Action) {
319→	data, ok := wire.FindCreateContext(req.Contexts, wire.CreateContextAlSi)
320→	if !ok {
321→		return
322→	}
323→	size, err := wire.AllocationSizeContext(data)
324→	if err != nil {
325→		ctx.Log.Debug("AlSi create context 长度非法", "len", len(data))
326→		return
327→	}
328→	// 超出 int64 的值只可能是畸形输入（AGENTS.md §8：用之前先校验边界）。
329→	if size == 0 || size > math.MaxInt64 {
330→		return
331→	}
332→	// 只在文件被新建/覆盖时预留。对一个**已存在**的文件做预留会悄悄改变
333→	// 它的磁盘占用，而客户端此时只是想打开它。
334→	switch action {
335→	case vfs.ActionCreated, vfs.ActionOverwritten, vfs.ActionSuperseded:
336→	default:
337→		return
338→	}
339→
340→	sp, ok := h.(vfs.SparseFile)
341→	if !ok {
342→		return
343→	}
344→	if err := sp.Preallocate(0, int64(size)); err != nil {
345→		ctx.Log.Debug("AlSi 预留空间失败", "size", size, "err", err)
346→	}
347→}
