349→// maximalAccessFor 返回 MAXIMUM_ALLOWED 在本树上应当授予的访问掩码。
350→func maximalAccessFor(t *Tree) wire.Access {
351→	if t.Writable() {
352→		return wire.Access(wire.MaximalAccessReadWrite)
353→	}
354→	return wire.Access(wire.MaximalAccessReadOnly)
355→}
