116→		CreationTime:   0x01d0000000000001,
117→		LastAccessTime: 0x01d0000000000002,
118→		LastWriteTime:  0x01d0000000000003,
119→		ChangeTime:     0x01d0000000000004,
120→		EndOfFile:      8 << 20,
121→		AllocationSize: 8 << 20,
122→		FileAttributes: wire.FileAttributeNormal,
123→		FileID:         0x1122334455667788,
124→		Name:           name,
125→	}
126→
127→	buf, err := wire.AppendDirEntry(nil, wire.FileIdBothDirectoryInformation, base)
128→	if err != nil {
129→		t.Fatalf("AppendDirEntry: %v", err)
130→	}
131→	// 未改写前：EaSize/ShortName/Reserved2 全零。
132→	if !bytes.Equal(buf[64:96], make([]byte, 32)) {
133→		t.Fatalf("基线目录项 [64:96] = %x, 期望全零", buf[64:96])
134→	}
135→
136→	attr := aaplDirAttr{
