140→	}
141→	if !attr.patchIDBothDirEntry(buf, 0) {
142→		t.Fatal("patchIDBothDirEntry 返回 false")
143→	}
144→
145→	// --- @64 EaSize ← max_access（小端） ---
146→	if v := binary.LittleEndian.Uint32(buf[64:68]); v != wire.MaximalAccessReadWrite {
147→		t.Errorf("EaSize(@64) = %#x, 期望 max_access %#x", v, wire.MaximalAccessReadWrite)
148→	}
149→	// --- @68 ShortNameLength=24, @69 Reserved=0 ---
150→	if buf[68] != 24 {
151→		t.Errorf("ShortNameLength(@68) = %d, 期望 24（Samba SSVAL(p,0,24)）", buf[68])
152→	}
153→	if buf[69] != 0 {
154→		t.Errorf("Reserved(@69) = %d, 期望 0", buf[69])
155→	}
156→	// --- @70 rfork_size（小端 uint64） ---
157→	if v := binary.LittleEndian.Uint64(buf[70:78]); v != attr.RsrcSize {
158→		t.Errorf("rfork_size(@70) = %#x, 期望 %#x", v, attr.RsrcSize)
159→	}
160→	// --- @78 压缩 FinderInfo（16 字节） ---
161→	if !bytes.Equal(buf[78:94], attr.FinderInfo[:]) {
162→		t.Errorf("FinderInfo(@78) = %x, 期望 %x", buf[78:94], attr.FinderInfo[:])
163→	}
164→	// --- @94 Reserved2 恒 0（不实现 NFS ACE 就不能填 unix_mode） ---
165→	if v := binary.LittleEndian.Uint16(buf[94:96]); v != 0 {
166→		t.Errorf("Reserved2(@94) = %#x, 期望 0", v)
167→	}
168→	// --- 改写不得越界污染 FileId 与文件名 ---
169→	if v := binary.LittleEndian.Uint64(buf[96:104]); v != base.FileID {
