171→	}
172→	if got, _ := wire.DecodeUTF16LE(buf[104:]); got != name {
173→		t.Errorf("FileName = %q, 期望 %q", got, name)
174→	}
175→	// --- 公共前缀（0..64）必须原封不动 ---
