	MaxAccess uint32
	// RsrcSize 是资源派生（AFP_Resource）的字节数。
	RsrcSize uint64
	// FinderInfo 是压缩后的 16 字节 FinderInfo。
	FinderInfo [aaplFinderInfoSize]byte
